def palindrome(str):
    return str==str[::-1]

def longest_palindrome(str):
    max=0
    ans=""
    for i in range(0,len(str)):
        sub=""
        for j in range(i+1,len(str)):
            sub=str[i:j+1]
            if palindrome(sub):
                if max < len(sub):
                    max = len(sub)
                    ans=sub
                        
    return ans,max
input=''''''
print(longest_palindrome(input))